package com.example.agendapersonal.ui;
import android.app.Activity;import android.os.Bundle;import android.widget.TextView;import com.example.agendapersonal.R;
public class AyudaActivity extends com.example.agendapersonal.ui.ActividadTematica {
 private MenuNavegacion menu;
 @Override protected void onCreate(Bundle b){super.onCreate(b);menu=new MenuNavegacion(this);setContentView(menu.getRaiz());menu.establecerContenido(R.layout.activity_ayuda);findViewById(R.id.botonMenu).setOnClickListener(v->menu.alternar());((TextView)findViewById(R.id.textoAyuda)).setText("Tu agenda funciona sin Internet.\n\nAbrí un registro para consultar sus datos, editarlo o cambiar su estado. El botón + agrega un registro. La lupa abre la búsqueda y los filtros; podés borrar el texto o las fechas para quitarlos.\n\nPrioridad y estado son independientes. Las prioridades son ALTÍSIMA, ALTA, MEDIA, BAJA y BAJÍSIMA. MUCHO, PENDIENTE, URGENTE, CRÍTICO y ATRASADO se calculan según la fecha. FINALIZADO, CANCELADO y POSTERGADO prevalecen sobre ese cálculo.\n\nPersonas, materias, especialidades y clasificaciones se pueden agregar desde sus listas o desde el formulario de una actividad.\n\nInvestigaciones permite consultar registros existentes y agregar observaciones. No permite crear investigaciones.\n\nEconomía distingue Ingresos, Pagos y Gastos. El gráfico utiliza únicamente movimientos FINALIZADOS. Un valor acordado en Freelance no genera ingresos automáticamente.\n\nAjustes permite exportar e importar CSV por módulo. La importación agrega registros nuevos y conserva los existentes. Para respaldar toda la agenda usá Ajustes → Copia completa y recuperación. El archivo se protege con una contraseña elegida por vos. Conservá el archivo y su contraseña fuera de la app. Al restaurar, se reemplazan los datos locales, se guarda el estado anterior y se solicita volver a iniciar sesión en Supabase. Los permisos de Android se mantienen por dispositivo.\n\nLa conexión con Supabase se configura desde Ajustes. Debe probarse con tu cuenta y las instalaciones que compartirán los datos. Los eventos pueden repetirse semanal, mensual o anualmente, o cada N días, semanas, meses o años. La finalización de una serie es opcional. Al editar o eliminar se elige una ocurrencia, esta y las siguientes o toda la serie; los estados se cambian por ocurrencia.\n\nNotificaciones en Ajustes permite habilitar avisos, horario preciso y la ventana flotante de actividades críticas de hoy. Las alarmas de tareas toman el inicio, y las de eventos su fecha. Sin hora se toma el inicio del día. Android requiere permisos elegidos por vos. Los avisos de escritorio requieren una aplicación de escritorio y no los genera esta instalación Android.");}
 @Override public void onBackPressed(){if(menu.estaAbierto())menu.cerrar();else super.onBackPressed();}
}
